import React from "react";
import {createRoot, type Root} from "react-dom/client";
import {flushSync} from "react-dom";
import {DataTable} from "../../src/components/ui/DataTable";
import {createControllerScope} from "../../src/components/workspace/controller-scope";
// Generated by scripts/qa-live-data.mjs with the same lexical scope as drawers.
// @ts-ignore fixture-only generated module
import {mountController} from "/controller.js";

let scope: ReturnType<typeof createControllerScope>, react: Root, root: HTMLElement;
let controller: {reload: () => Promise<unknown>; dispose: () => void};
const columns = [
  {id:"username",header:"Usuario",accessorKey:"username",sortable:true},
  {id:"revision",header:"Revisión",accessorKey:"revision"},
];
const filters = [{id:"search",label:"Buscar",accessorKey:"username",type:"text" as const}];
const actions = [{id:"export",label:"Exportar"}];
const rows: Record<string, unknown>[] = [];
function mount(target: string) {
  scope?.dispose(); react?.unmount();
  sessionStorage.setItem("panel-active-target-scope",target);
  sessionStorage.setItem("panel-active-bridge-session",target);
  window.dispatchEvent(new CustomEvent("luxipanel:target-changed"));
  document.getElementById("host")!.innerHTML = '<section data-internal-module="users" id="drawer"><label>Borrador<input id="draft"></label><div id="table"></div><div style="height:180px"></div></section>';
  root = document.getElementById("drawer")!;
  scope = createControllerScope(root,new URL("/panel/users",location.href));
  react = createRoot(document.getElementById("table")!);
  flushSync(()=>react.render(<DataTable tableId="fixture-users" columns={columns} filters={filters} data={rows} quickActions={actions}/>));
  controller = mountController(scope,root);
  void controller.reload();
}
mount("A");
(window as any).qa = {
  visible(value: boolean) {root.hidden=!value; scope.setVisible(value);},
  reload: () => controller.reload(),
  mount,
  change() {window.dispatchEvent(new CustomEvent("lxp:data:change",{detail:{resources:["users/system"]}}));},
  dispose() {scope.dispose();react.unmount();},
};
